import time
from fractions import Fraction


class TokenBucket:
    """A token bucket rate limiter. See TASK.md."""

    def __init__(self, rate, capacity, clock=time.monotonic):
        if not rate > 0:
            raise ValueError("rate must be greater than 0")
        if not capacity > 0:
            raise ValueError("capacity must be greater than 0")
        self._rate = rate
        self._capacity = capacity
        self._clock = clock
        self._tokens = capacity  # a new bucket is full
        self._last = clock()

    def _projected(self, now):
        """Tokens the bucket would hold at time `now`, without changing state.

        Clock steps backwards add nothing (rule 8).
        """
        elapsed = now - self._last
        if elapsed <= 0:
            return self._tokens
        gained = self._rate * elapsed
        if self._tokens + gained >= self._capacity:
            return self._capacity
        return self._tokens + gained

    def _refill(self):
        now = self._clock()
        self._tokens = self._projected(now)
        self._last = now
        return self._tokens

    def _check_cost(self, cost):
        if not cost > 0:
            raise ValueError("cost must be greater than 0")
        if cost > self._capacity:
            raise ValueError("cost must not exceed capacity")

    def take(self, cost=1):
        """Remove `cost` tokens and return True if available, else return False."""
        self._check_cost(cost)
        tokens = self._refill()
        if tokens >= cost:
            self._tokens = tokens - cost
            return True
        return False

    def available(self):
        """Return the number of tokens in the bucket now."""
        return self._refill()

    def wait_time(self, cost=1):
        """Seconds until take(cost) would succeed; 0 if it would succeed now.

        Does not change the bucket state.
        """
        self._check_cost(cost)
        tokens = self._projected(self._clock())
        if tokens >= cost:
            return 0
        missing = cost - tokens
        if isinstance(missing, float) or isinstance(self._rate, float):
            return missing / self._rate
        # int/Fraction inputs: exact result
        return Fraction(missing) / Fraction(self._rate)
